problems.solution:
package main

import "fmt"

func twoSum(nums []int, target int) (int, int) {
  seen := map[int]int{}
  for i, n := range nums {
    if j, ok := seen[target-n]; ok {
      return j, i
    }
    seen[n] = i
  }
  return -1, -1
}

func main() {
  i, j := twoSum([]int{2, 7, 11, 15}, 9)
  fmt.Printf("%d %d\n", i, j)
}

