problems.solution:
package main

import (
  "fmt"
  "slices"
  "strings"
)

func main() {
  text := "go go java rust go java"
  freq := map[string]int{}
  for _, w := range strings.Fields(text) {
    freq[w]++
  }
  var keys []string
  for k, v := range freq {
    if v > 1 {
      keys = append(keys, k)
    }
  }
  slices.Sort(keys)
  for _, k := range keys {
    fmt.Printf("%s:%d\n", k, freq[k])
  }
}
